#include <iostream>
using namespace std;
int main(){int n;scanf("%d",&n);vector<long long>a(n);
for(int i=0;i<n;++i)scanf("%lld",&a[i]);
long long reach=0;
for(int i=0;i<n;++i){
if(i>reach){printf("NO\n");return 0;}
reach=max(reach,(long long)i+a[i]);}
printf("YES\n");return 0;}

